// The constant's NatSpec (CDPVault.sol:354) and cash's comment say a held-down pool pays a redeemer "1% an hour
// here, after the fee has eaten the first five". The fee is 50 bps plus the burn's share of the fee base over the
// divisor: it reaches the 5% cap only for a burn of about 9% of the fee base. A small burn pays about 0.5-0.75%,
// so a pool held down ONE paced hour already pays it more at the pre-fall price than it burned, and a two-hour
// hold pays 1.3% over. The bound stated for the accepted item ("the fee eats the first five") does not hold.

import {Test} from "forge-std/Test.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {ParameterizedVault} from "src/ParameterizedVault.sol";
import {ImdUSD} from "src/ImdUSD.sol";
import {MockIMD} from "src/MockIMD.sol";
import {TreasuryFactory} from "src/TreasuryFactory.sol";
import {ISwarmFeed} from "src/interfaces/ISwarmFeed.sol";
import {APPROVED_OPERATOR, CHAINLINK_ETH_USD, TREASURY_FACTORY} from "src/DeploymentConfig.sol";

contract SbFeed is ISwarmFeed {
    uint256 public constant maxAge = 1 hours;
    uint256 private value;
    uint64 private updatedAt;

    constructor(uint256 v) {
        set(v);
    }

    function set(uint256 v) public {
        value = v;
        updatedAt = uint64(block.timestamp);
    }

    function latestValue() external view returns (uint256, uint64) {
        return (value, updatedAt);
    }

    function isStale() external view returns (bool) {
        return block.timestamp - updatedAt > maxAge;
    }
}

contract SbAggregator {
    function decimals() external pure returns (uint8) {
        return 8;
    }

    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80) {
        return (1, 2000e8, block.timestamp, block.timestamp, 1);
    }
}

contract SmallRedemptionBreakEvenTest is Test {
    address private constant BOOK = address(0xB00C);
    address private constant HOLDER = address(0x401D);
    uint256 private constant DOLLAR = uint256(1 ether) * 1e18 / 2000 ether; // IMD/ETH at $1

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    SbFeed private primary;
    SbFeed private health;
    SbFeed private spot;
    uint256 private imdEth = DOLLAR;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new SbAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        primary = new SbFeed(DOLLAR);
        health = new SbFeed(0.85 ether);
        spot = new SbFeed(DOLLAR);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(spot)
        );
        stable = vault.stablecoin();
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(BOOK, 2_000_000 ether);
        imd.mint(HOLDER, 300_000 ether);
        vm.stopPrank();
        vm.startPrank(BOOK);
        imd.approve(address(vault), type(uint256).max);
        vault.lock(1_800_000 ether);
        vault.draw(900_000 ether); // 200%: the candidate; a $1M book
        vm.stopPrank();
        vm.startPrank(HOLDER);
        imd.approve(address(vault), type(uint256).max);
        vault.lock(300_000 ether);
        vault.draw(100_000 ether);
        vm.stopPrank();
        for (uint256 i; i < 48; ++i) {
            _hour();
        }
        assertEq(vault.backingPerUnit(), 1e18, "a par book");
    }

    function _next(uint256 seconds_) private {
        vm.warp(block.timestamp + seconds_);
        vm.roll(block.number + 1 + seconds_ / 12);
        primary.set(imdEth);
        spot.set(imdEth);
        health.set(0.85 ether);
    }

    function _hour() private {
        _next(1 hours);
        vault.pace();
    }

    /// @dev A 20% step held and paced for ONE hour; a 5,000 imdUSD burn (0.5% of the 1M fee base: fee 50 + 25 bps).
    function test_oneHourHoldAlreadyPaysASmallRedeemerMoreThanItBurned() public {
        uint256 preFall = DOLLAR;
        imdEth = DOLLAR * 80 / 100;
        _next(12);
        _hour();
        assertEq(vault.redemptionFeeBps(5_000 ether), 75, "the fee on a small burn is 75 bps, not the 500 cap");
        vm.prank(HOLDER);
        uint256 gemOut = vault.cash(5_000 ether, 0, BOOK);
        uint256 valueAtPreFall = Math.mulDiv(gemOut, preFall * 2000, 1e18);
        // EXPECTED per the NatSpec: a hold shorter than five paced hours pays at most what was burned.
        // ACTUAL: 5,000 imdUSD takes IMD worth about 5,012 at the pre-fall price after one paced hour.
        assertLe(valueAtPreFall, 5_000 ether, "one paced hour pays a small redeemer more than it burned");
    }

    /// @dev Two paced hours: 1.3% over.
    function test_twoHourHoldPaysASmallRedeemerOnePercentOver() public {
        uint256 preFall = DOLLAR;
        imdEth = DOLLAR * 80 / 100;
        _next(12);
        _hour();
        _hour();
        vm.prank(HOLDER);
        uint256 gemOut = vault.cash(5_000 ether, 0, BOOK);
        uint256 valueAtPreFall = Math.mulDiv(gemOut, preFall * 2000, 1e18);
        assertLe(valueAtPreFall, 5_000 ether, "two paced hours pay a small redeemer more than it burned");
    }
}

